#!/bin/sh
# Generate install_pg_tle.sql (called by `make managed`; don't run by hand).
#
#   gen_pg_tle.sh <version>
#
# The generated file works for a fresh install and for an upgrade:
#  - pg_index_deps not registered with pg_tle: register <version>.
#  - already registered (older version): register every missing update path
#    (from the pg_index_deps--A--B.sql scripts) and make <version> the default,
#    so ALTER EXTENSION pg_index_deps UPDATE works.
set -eu
ver=$1
ext=pg_index_deps
body() { grep -v '^\\echo' "$1"; }

cat <<EOF
-- $ext $ver via pg_tle (generated by make managed, do not edit)
-- New install:     \\i install_pg_tle.sql   then  CREATE EXTENSION $ext;
-- Older version:   \\i install_pg_tle.sql   then  ALTER EXTENSION $ext UPDATE;
DO \$${ext}_install\$
BEGIN
IF NOT EXISTS (SELECT 1 FROM pgtle.available_extensions() WHERE name = '$ext') THEN
PERFORM pgtle.install_extension('$ext', '$ver',
  'which queries depend on each index; drop-impact check',
\$_pgtle_\$
CREATE SCHEMA IF NOT EXISTS index_deps;
EOF
body "$ext--$ver.sql"
echo '$_pgtle_$);'
echo 'ELSE'
for f in $(ls $ext--*--*.sql 2>/dev/null | sort -V); do
	pair=${f#$ext--}; pair=${pair%.sql}
	from=${pair%--*}; to=${pair#*--}
	cat <<EOF
IF NOT EXISTS (SELECT 1 FROM pgtle.extension_update_paths('$ext')
                WHERE source = '$from' AND target = '$to' AND path IS NOT NULL) THEN
PERFORM pgtle.install_update_path('$ext', '$from', '$to',
\$_pgtle_\$
EOF
	body "$f"
	echo '$_pgtle_$);'
	echo 'END IF;'
done
cat <<EOF
PERFORM pgtle.set_default_version('$ext', '$ver');
END IF;
END
\$${ext}_install\$;
EOF
